"use client";
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { parseQuery, serializeQuery, search, type Schema, type Query } from '@/app/lib/query-state';
import { withQuery } from '@/app/lib/routes';

export function useUrlQuery<S extends Schema>(schema: S, enabled = true) {
  const pathname = usePathname();
  const params = useSearchParams();
  const router = useRouter();
  const raw = params.toString();
  const signature = JSON.stringify(Object.fromEntries(Object.entries(schema).map(([k, v]) => [k, v.default])));
  // Schema readers supply their enum lists from the active client's data.
  const values = useMemo(() => parseQuery(schema, new URLSearchParams(raw)), [schema, raw]);
  const canonical = serializeQuery(schema, values);
  const pending = useRef<{ pathname: string; raw: string; patch: Partial<Query<S>>; history: 'push' | 'replace' } | null>(null);
  const lastCanonical = useRef('');
  useEffect(() => {
    const key = `${pathname}?${raw}=>${canonical}`;
    if (!enabled) return;
    if (canonical !== raw && lastCanonical.current !== key) {
      lastCanonical.current = key;
      router.replace(withQuery(pathname, canonical), { scroll: false });
    } else if (canonical === raw) lastCanonical.current = '';
  }, [pathname, raw, canonical, router, signature, enabled]);
  const update = useCallback((patch: Partial<Query<S>>, history: 'push' | 'replace' = 'replace') => {
    if (pending.current?.pathname === pathname && pending.current.raw === raw) {
      Object.assign(pending.current.patch, patch);
      if (history === 'push') pending.current.history = history;
      return;
    }
    pending.current = { pathname, raw, patch, history };
    queueMicrotask(() => {
      const next = pending.current;
      pending.current = null;
      if (!next) return;
      const query = serializeQuery(schema, { ...values, ...next.patch });
      if (query !== raw) router[next.history](withQuery(pathname, query), { scroll: false });
    });
  }, [pathname, raw, router, schema, values]);
  const field = <K extends keyof Query<S>>(key: K, history: 'push' | 'replace' = 'replace') => (next: string | number | ((old: Query<S>[K]) => Query<S>[K])) => {
    const value = typeof next === 'function' ? next(values[key]) : next;
    update({ ...(key !== 'page' && 'page' in schema ? { page: 1 } : {}), [key]: value } as Partial<Query<S>>, history);
  };
  return { values, update, field, query: canonical, pathname };
}

/** Draft typing is local; committed operational searches use replace after 300ms. */
export function useUrlSearch(value: string, commit: (value: string) => void) {
  const [draft, setDraft] = useState<string | null>(null);
  const [privateQuery, setPrivateQuery] = useState('');
  const commitRef = useRef(commit);
  commitRef.current = commit;
  const path = usePathname();
  useEffect(() => { setDraft(null); setPrivateQuery(''); }, [value, path]);
  useEffect(() => {
    if (draft === null) return;
    const timer = setTimeout(() => {
      const safe = search.parse(draft);
      setPrivateQuery(safe || !draft ? '' : draft);
      commitRef.current(safe);
    }, 300);
    return () => clearTimeout(timer);
  }, [draft]);
  return { input: draft ?? value, effective: privateQuery || value, set: setDraft };
}

/** Query codecs are shared by links, parsers, and the URL hook. Defaults never serialize. */
export type Value = string | number;
export type Codec<T extends Value = Value> = { default: T; parse: (raw: string) => T; print: (value: Value) => string };
export type Schema = Record<string, Codec>;
export type Query<S extends Schema> = { [K in keyof S]: S[K]['default'] };
export const slug = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

export function choice<T extends string>(values: readonly T[], fallback: T): Codec<T> {
  return { default: fallback, parse: raw => values.find(v => slug(v) === raw.toLowerCase()) ?? fallback, print: value => slug(String(value)) };
}
export function optionalChoice(values: readonly string[], fallback = ''): Codec<string> {
  return choice([fallback, ...values], fallback);
}
export function integer(fallback = 1, max = 10000): Codec<number> {
  return { default: fallback, parse: raw => /^\d+$/.test(raw) && +raw > 0 && +raw <= max ? +raw : fallback, print: String };
}
export function pageSize(all?: false): Codec<number>;
export function pageSize(all: true): Codec<number | 'all'>;
export function pageSize(all = false): Codec<number | 'all'> {
  return { default: 10, parse: raw => all && raw === 'all' ? 'all' : [10, 30, 50, 100].includes(+raw) ? +raw : 10, print: String };
}
export function validDate(raw: string) {
  return /^\d{4}-\d{2}-\d{2}$/.test(raw) && raw >= '2000-01-01' && raw <= '2100-12-31' && new Date(`${raw}T00:00:00Z`).toISOString().slice(0, 10) === raw;
}
export function date(fallback = ''): Codec<string> {
  return { default: fallback, parse: raw => { try { return validDate(raw) ? raw : fallback; } catch { return fallback; } }, print: String };
}
export const dateRange: Codec<string> = {
  default: '', parse: raw => {
    if (raw === 'today') return raw;
    const parts = raw.split('..');
    if (parts.length > 2 || parts.some(part => !date().parse(part))) return '';
    return parts.sort().join('..');
  }, print: String,
};
// A search URL may contain operational vocabulary / ticket codes, never names,
